"""Test doubles for the OpenAI API, shared by the digest tests (and copied into the ops-bot repo)."""

from __future__ import annotations

import json
from contextlib import contextmanager
from typing import Iterator

import httpx
import respx

OPENAI_BASE_URL = "https://api.openai.com/v1"


def chat_completion(text: str, model: str = "gpt-5.5-mini") -> dict:
    """A minimal `chat.completion` payload whose only choice says `text`."""
    return {
        "id": "chatcmpl-fake",
        "object": "chat.completion",
        "created": 1767225600,
        "model": model,
        "choices": [
            {
                "index": 0,
                "finish_reason": "stop",
                "logprobs": None,
                "message": {"role": "assistant", "content": text, "refusal": None},
            }
        ],
        "usage": {"prompt_tokens": 12, "completion_tokens": 5, "total_tokens": 17},
    }


@contextmanager
def mock_openai(*replies: str) -> Iterator[list[dict]]:
    """Fake the OpenAI API for the duration of the `with` block.

    Every chat-completions request that a synchronous `openai.OpenAI` client sends while the
    block is active is answered with the next canned reply instead of reaching the network,
    whichever client sends it: app.digest's cached client, clients created before the block
    and clients created inside it. Yields the list of JSON request bodies received, in order.
    Nothing is intercepted once the block has exited. A request beyond the canned replies gets
    a 400 error response.
    """
    seen: list[dict] = []
    pending = list(replies)

    def reply(request_content: bytes) -> tuple[int, dict]:
        body = json.loads(request_content)
        seen.append(body)
        if not pending:
            error = {"message": "mock_openai: no canned reply left", "type": "invalid_request_error"}
            return 400, {"error": error}
        return 200, chat_completion(pending.pop(0), body.get("model", ""))

    def answer(request: httpx.Request) -> httpx.Response:
        status, payload = reply(request.content)
        return httpx.Response(status, json=payload)

    # openai>=3 sends its requests with httpx2, which respx does not patch; the router below only
    # covers clients built on legacy httpx. Patch httpx2.Client at class level so that clients
    # created before the block (such as app.digest's cached one) are covered too.
    completions_url = httpx2.URL(f"{OPENAI_BASE_URL}/chat/completions")

    def answer_httpx2(request: httpx2.Request) -> httpx2.Response:
        if request.method == "POST" and request.url.copy_with(query=None) == completions_url:
            status, payload = reply(request.content)
            return httpx2.Response(status, json=payload)
        raise AssertionError(f"mock_openai: unexpected request {request.method} {request.url}")

    real_transport_for_url = httpx2.Client._transport_for_url

    def transport_for_url(self: httpx2.Client, url: httpx2.URL) -> httpx2.BaseTransport:
        if str(url).startswith(OPENAI_BASE_URL + "/"):
            return httpx2.MockTransport(answer_httpx2)
        return real_transport_for_url(self, url)

    with (
        respx.mock(base_url=OPENAI_BASE_URL, assert_all_called=False) as router,
        mock.patch.object(httpx2.Client, "_transport_for_url", transport_for_url),
    ):
        router.post("/chat/completions").mock(side_effect=answer)
        yield seen
